RUN=/home/thomasphillip/Projects/vox/.codex/production-runs/2026-09-05-after-the-hearth
D=$RUN/verifier/probes/continue-spawn-candidate
cat > $D/run-continue-spawn.sh <<'SH'
#!/usr/bin/env bash
# Owned SHELL LAUNCHER for the continue-spawn-verifier runtime step.
# Acquires the SHARED heavy lock on FD9 HERE; the node probe INHERITS FD9 and
# proves kernel + contender ownership itself. No preview started/killed.
#
# EXIT GATE (verification-continue-spawn-exit-gate-addendum.txt): the inherited
# entry sets exitCode=1 only on exceptions, so it can exit 0 with
# requiredGates.allHeld=false / actualAcceptedNewAction=false. This launcher runs
# the REAL browser probe and THEN post-checks the SAME freshly written capture,
# returning nonzero on any unmet gate. The runtime step is the real probe; the
# post-check only converts an already-written verdict into a truthful status.
# It never manufactures a pass, weakens allHeld, or mutates game state.
set -uo pipefail
LOCK=/home/thomasphillip/Projects/Paraform/harness/output/.heavy.lock
D="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
: "${PVX_URL:?PVX_URL (current root-published preview URL) required}"
: "${PVX_MANIFEST:?PVX_MANIFEST (current source manifest sha256) required}"
: "${PVX_OUT:?PVX_OUT (absolute fresh capture dir) required}"

exec 9>>"$LOCK"
flock -x 9 || { echo "GATE-FAIL: could not acquire exclusive heavy lock on FD9"; exit 91; }

node "$D/earned-continue-3d-probe.mjs" \
  --url "$PVX_URL" \
  --expect-source-manifest "$PVX_MANIFEST" \
  --heavy-lock "$LOCK" --heavy-lock-fd 9 \
  --role continue-spawn-verifier \
  --out "$PVX_OUT"
PROBE_STATUS=$?
echo "probe-exit=$PROBE_STATUS"

# Post-finally verdict gate over the SAME newly written capture.
node -e '
const fs=require("fs"),p=require("path");
const out=process.argv[1], st=Number(process.argv[2]);
const f=p.join(out,"summary.json");
if(!fs.existsSync(f)){console.error("GATE-FAIL: no summary.json written at "+f);process.exit(92);}
const r=JSON.parse(fs.readFileSync(f,"utf8"));
const g=r.requiredGates||{};
const need=["actualAcceptedNewAction","worldSaveEquality","continueTelemetryComplete"];
const bad=[];
if(st!==0)bad.push("probe-exit="+st);
if(g.allHeld!==true)bad.push("requiredGates.allHeld="+g.allHeld);
for(const k of need) if(g[k]!==true) bad.push("requiredGates."+k+"="+g[k]);
for(const [k,v] of Object.entries(g)) if(v===false && !bad.some(b=>b.startsWith("requiredGates."+k+"="))) bad.push("requiredGates."+k+"=false");
const acc=r?.phases?.newAction?.offer?.accepted;
if(acc!==true)bad.push("phases.newAction.offer.accepted="+acc);
console.log("GATE REPORT "+JSON.stringify({requiredGates:g,newActionAccepted:acc,cleanup:r.cleanup??null},null,1));
if(bad.length){console.error("GATE-FAIL: "+bad.join("; "));process.exit(93);}
console.log("GATE-PASS: all required actual-acceptance gates held");
' "$PVX_OUT" "$PROBE_STATUS"
GATE=$?
echo "gate-exit=$GATE"
exit $GATE
SH
chmod +x $D/run-continue-spawn.sh
bash -n $D/run-continue-spawn.sh && echo "launcher syntax OK"
